extern "C" {

static const int TILE = 16;

void load_k_row_tile(int path[N][N], int k, int j_start, int buf[TILE])
{
#pragma HLS ARRAY_PARTITION variable=buf complete dim=1
    for (int j = 0; j < TILE; j++) {
