**Key changes made:**

1. **Two sets of buffers**: Created `local_tile_0/1`, `kj_row_0/1`, `ik_col_0/1` as ping-pong pairs.

2. **Flattened tile loop**: Changed the nested `i_start/j_start` loops into a single flat loop over tile index `t` (0 to 143), making it easier to track "current" and "next" tiles.

3. **Pre-load first tile**: Before the main loop, tile 0 is loaded into buffer set 0.

4. **Ping-pong alternation**: Using `ping = t % 2` to select which buffer to compute from and which to load into. While computing tile `t` from buffer `ping`, the next tile `t+1` is loaded into buffer `1-ping`.

5. **Overlap**: Load of tile `t+1` happens concurrently with compute+store of tile `t`, hiding memory latency behind computation.

Looking at the current code, I need to apply memory coalescing by:
1. Changing the `path` pointer to `ap_uint<512>*` (wide bus type)
2. Including the wide bus header `../../../common/mc.h`
3. Using `memcpy_wide_bus_read` and `memcpy_wide_bus_write` helper functions
4. Updating INTERFACE pragmas for wide bus
5. Adding cyclic array partitioning to local buffers

The key challenge is that `path` is a 2D `int` array (N×N = 180×180 = 32400 ints = 129600 bytes). With a 512-bit (64-byte) wide bus, each transaction carries 16 ints.

```cpp
#include "floyd-warshall.h"
#include "../../../common/mc.h"

extern "C" {

static const int TILE = 16;

// Wide bus helper: read TILE ints from a flat offset into buf
// path_flat is row-major: index [i][j] -> offset i*N + j
// We use memcpy_wide_bus_read for int (32-bit elements)
// 512 bits = 16 ints per transaction

void load_k_row_tile_wide(MARS_WIDE_BUS_TYPE *path, int k, int j_start, int buf[TILE])
{
#pragma HLS ARRAY_PARTITION variable=buf complete dim=1
#pragma HLS INLINE
    int flat_offset = k * N + j_start;
    memcpy_wide_bus_read_int(buf, 0, path, flat_offset * sizeof(int), sizeof(int) * TILE);
}

void load_ik_col_tile_scalar(MARS_WIDE_BUS_TYPE *path, int k, int i_start, int buf[TILE])
{
#pragma HLS ARRAY_PARTITION variable=buf complete dim=1
#pragma HLS INLINE
    // Column reads are strided - must do scalar reads
    for (int i = 0; i < TILE; i++) {
#pragma HLS PIPELINE II=1
        int ii = i_start + i;
        if (ii < N) {
            int tmp[1];
            memcpy_wide_bus_read_int(tmp, 0, path, (ii * N + k) * sizeof(int), sizeof(int));
            buf[i] = tmp[0];
        } else {
            buf[i] = 0;
        }
    }
}

void load_tile_wide(MARS_WIDE_BUS_TYPE *path, int i_start, int j_start, int tile[TILE][TILE])
{
#pragma HLS ARRAY_PARTITION variable=tile complete dim=2
#pragma HLS INLINE
    for (int i = 0; i < TILE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
        int ii = i_start + i;
        if (ii < N) {
            int row_buf[TILE];
#pragma HLS ARRAY_PARTITION variable=row_buf complete dim=1
            int flat_offset = ii * N + j_start;
            memcpy_wide_bus_read_int(row_buf, 0, path, flat_offset * sizeof(int), sizeof(int) * TILE);
            for (int j = 0; j < TILE; j++) {
#pragma HLS UNROLL
                int jj = j_start + j;
                tile[i][j] = (jj < N) ? row_buf[j] : 0;
            }
        } else {
            for (int j = 0; j < TILE; j++) {
#pragma HLS UNROLL
                tile[i][j] = 0;
            }
        }
    }
}

void compute_tile(int tile[TILE][TILE], int ik_col[TILE], int kj_row[TILE])
{
#pragma HLS ARRAY_PARTITION variable=tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=ik_col complete dim=1
#pragma HLS ARRAY_PARTITION variable=kj_row complete dim=1
    for (int i = 0; i < TILE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
        for (int j = 0; j < TILE; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=tile inter false
            int new_val = ik_col[i] + kj_row[j];
            int old_val = tile[i][j];
            tile[i][j] = (old_val < new_val) ? old_val : new_val;
        }
    }
}

void store_tile_wide(MARS_WIDE_BUS_TYPE *path, int i_start, int j_start, int tile[TILE][TILE])
{
#pragma HLS ARRAY_PARTITION variable=tile complete dim=2
#pragma HLS INLINE
    for (int i = 0; i < TILE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
        int ii = i_start + i;
        if (ii < N) {
            int row_buf[TILE];
#pragma HLS ARRAY_PARTITION variable=row_buf complete dim=1
            for (int j = 0; j < TILE; j++) {
#pragma HLS UNROLL
                row_buf[j] = tile[i][j];
            }
            int flat_offset = ii * N + j_start;
            // Only write valid columns (handle boundary)
            int valid_cols = TILE;
            if (j_start + TILE > N) valid_cols = N - j_start;
            if (valid_cols > 0) {
                memcpy_wide_bus_write_int(path, flat_offset * sizeof(int), row_buf, 0, sizeof(int) * valid_cols);
            }
        }
    }
}

void kernel_floyd_warshall(
    MARS_WIDE_BUS_TYPE *path)
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem depth=32400 \
    max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=path bundle=control
